from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    n = len(numbers)
    for i in range(n):
        for j in range(i + 1, n):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    result = []
    i = 0
    n = len(paren_string)

    while i < n:
        if paren_string[i] == '(':
            stack.append(i)
            i += 1
        elif stack:
            open_idx = stack.pop()
            result.append(paren_string[open_idx + 1:i])
            i += 1
        else:
            i += 1

    return result
